#!/usr/bin/env python3
"""Reference model for `seqtk seq` (part 1 options: -q -X -n -Q -V -F -A -x -U -S -M -c).

Options modelled: -q INT, -X INT, -n CHAR, -Q INT, -V, -F CHAR, -A/-a, -x, -U, -S,
-M FILE, -c.  All other seq options are assumed off / default (-l 0, no -r/-R/-C/-N/-1/-2/-L/-f).
"""
import sys

SPACE = (0x20, 0x09, 0x0a, 0x0b, 0x0c, 0x0d)
INT_MAX = 2147483647


def isspace(b):
    return b in SPACE


def isdigit(b):
    return 0x30 <= b <= 0x39


def i32(x):
    x &= 0xFFFFFFFF
    return x - 0x100000000 if x >= 0x80000000 else x


def sc(b):                      # signed char
    return b - 256 if b >= 128 else b


def atoi(bs):
    """C atoi() on a byte string (leading ws, optional sign, digits)."""
    i, n = 0, len(bs)
    while i < n and isspace(bs[i]):
        i += 1
    sign = 1
    if i < n and bs[i] in (0x2b, 0x2d):
        if bs[i] == 0x2d:
            sign = -1
        i += 1
    v = 0
    while i < n and isdigit(bs[i]):
        v = v * 10 + (bs[i] - 0x30)
        i += 1
    return i32(sign * v)


# ---------------------------------------------------------------- kseq parser
def parse(data):
    """Yield (name, comment, seq, qual) as bytes.  kseq-like."""
    recs = []
    i, n = 0, len(data)
    pending = None                       # '>' / '@' already consumed
    while True:
        if pending is None:
            while i < n and data[i] not in (0x3e, 0x40):
                i += 1
            if i >= n:
                break
            i += 1
        pending = None
        # ---- header
        j = i
        while j < n and not isspace(data[j]):
            j += 1
        name = data[i:j]
        comment = b''
        if j < n and data[j] != 0x0a:
            k = j
            while k < n and data[k] != 0x0a:
                k += 1
            comment = data[j + 1:k]
            j = k
        i = j + 1 if j < n else n
        # ---- sequence
        seq = bytearray()
        term = None
        while i < n:
            c = data[i]
            if c in (0x3e, 0x2b, 0x40):
                term = c
                i += 1
                break
            if c == 0x0a:
                i += 1
                continue
            k = i
            while k < n and data[k] != 0x0a:
                k += 1
            line = data[i:k]
            if line.endswith(b'\r'):
                line = line[:-1]
            seq += line
            i = k + 1 if k < n else n
        qual = bytearray()
        if term == 0x2b:
            while i < n and data[i] != 0x0a:   # discard rest of '+' line
                i += 1
            i += 1
            while i < n and len(qual) < len(seq):
                k = i
                while k < n and data[k] != 0x0a:
                    k += 1
                line = data[i:k]
                if line.endswith(b'\r'):
                    line = line[:-1]
                qual += line
                i = k + 1 if k < n else n
            if len(qual) != len(seq):
                break                          # discard + stop parsing
            recs.append((name, comment, bytes(seq), bytes(qual)))
        else:
            recs.append((name, comment, bytes(seq), b''))
            if term is not None:
                pending = term
    return recs


# ---------------------------------------------------------------- -M reader
def read_regions(path):
    """Return {name: [(beg,end), ...]} or None when the file cannot be opened."""
    try:
        raw = open(path, 'rb').read()
        if raw[:2] == b'\x1f\x8b':
            import gzip
            raw = gzip.decompress(raw)
    except Exception:
        return None
    h = {}
    for line in raw.split(b'\n'):
        if line.endswith(b'\r'):
            line = line[:-1]
        if raw and line == b'' and line is not None:
            # a truly empty line still produces one empty field -> name ""
            pass
        # split on every single isspace byte (kseq ks_getuntil semantics)
        fields, cur = [], bytearray()
        for b in line:
            if isspace(b):
                fields.append(bytes(cur))
                cur = bytearray()
            else:
                cur.append(b)
        fields.append(bytes(cur))
        name = fields[0]
        beg = end = -1
        if len(fields) > 1:
            f = fields[1]
            if len(f) > 0 and isdigit(f[0]):
                beg = atoi(f)
                if len(fields) > 2:
                    g = fields[2]
                    if len(g) > 0 and isdigit(g[0]):
                        end = atoi(g)
        if end < 0:
            end = beg
            beg = beg - 1
        if beg < 0:
            beg, end = 0, INT_MAX
        h.setdefault(name, []).append((beg, end))
    return h


# ---------------------------------------------------------------- transforms
def mask_byte(c, mask_chr):
    if mask_chr:
        return mask_chr
    return c + 32 if 0x41 <= c <= 0x5a else c      # tolower()


def run(data, q=0, X=255, n=0, Q=33, V=False, F=0, A=False,
        x=False, U=False, S=False, M=None, c=False):
    """M: path to the -M file, or None."""
    regs = read_regions(M) if M is not None else None
    out = bytearray()
    for name, comment, seq, qual in parse(data):
        s = bytearray(seq)
        qs = bytearray(qual)
        l = len(s)
        # ---- -S : in-place squeeze of isspace, buffer LENGTHS UNCHANGED
        if S:
            j = 0
            for i in range(len(s)):
                if not isspace(s[i]):
                    if len(qs):
                        qs[j] = qs[i]
                    s[j] = s[i]
                    j += 1
            l = j
        # ---- quality masking (-q / -X)
        if len(qs) and q > 0:
            thres = i32(q + Q)
            for i in range(l):
                v = sc(qs[i])
                if v < thres or v > X:
                    s[i] = mask_byte(s[i], n)
        # ---- -U
        if U:
            for i in range(l):
                if 0x61 <= s[i] <= 0x7a:
                    s[i] -= 32
        # ---- -x
        if x:
            for i in range(l):
                if 0x61 <= s[i] <= 0x7a:
                    s[i] = mask_byte(s[i], n)
        # ---- -M / -c
        if regs is not None:
            hit = bytearray(l)
            r = regs.get(name)
            if r is not None:
                for (b, e) in r:
                    for i in range(max(0, b), min(e, l)):
                        hit[i] = 1
            if c:
                for i in range(l):
                    hit[i] ^= 1
            for i in range(l):
                if hit[i]:
                    s[i] = mask_byte(s[i], n)
        # ---- -F  (qual buffer replaced, length := l)
        if F:
            qs = bytearray([F] * l)
        # ---- -V
        if len(qs) and V:
            for i in range(l):
                qs[i] = (qs[i] + 33 - Q) & 0xFF
        # ---- output
        fq = len(qs) > 0 and not A
        out += (b'@' if fq else b'>') + name
        if comment:
            out += b' ' + comment
        out += b'\n' + bytes(s) + b'\n'
        if fq:
            out += b'+\n' + bytes(qs) + b'\n'
    return bytes(out)


if __name__ == '__main__':
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument('-q', type=int, default=0)
    ap.add_argument('-X', type=int, default=255)
    ap.add_argument('-n', default='')
    ap.add_argument('-Q', type=int, default=33)
    ap.add_argument('-F', default='')
    ap.add_argument('-M', default=None)
    ap.add_argument('-V', action='store_true')
    ap.add_argument('-A', action='store_true')
    ap.add_argument('-x', action='store_true')
    ap.add_argument('-U', action='store_true')
    ap.add_argument('-S', action='store_true')
    ap.add_argument('-c', action='store_true')
    ap.add_argument('file')
    a = ap.parse_args()
    nb = a.n.encode('latin1')
    fb = a.F.encode('latin1')
    sys.stdout.buffer.write(run(open(a.file, 'rb').read(),
                                q=a.q, X=a.X, n=(nb[0] if nb else 0), Q=a.Q,
                                V=a.V, F=(fb[0] if fb else 0), A=a.A, x=a.x,
                                U=a.U, S=a.S, M=a.M, c=a.c))

